{
  "probability": 0.71,
  "range_low": 0.60,
  "range_high": 0.80,
  "summary": [
    "Bayesian posterior probability of reaching 900 Mediterranean migrant deaths by end of March 2026 is 71%.",
    "As of late February 2026, ~606 deaths/missing were recorded, meaning March would need roughly 294 more fatalities, making pace continuation a key driver.",
    "Upward drivers include storms/rough seas and a potential large maritime disaster; downward pressures include data-reporting lags and SAR improvements.",
    "Calibrated stance: 71% center with a 60–80% range reflects substantial uncertainty and potential factor correlations."
  ],
  "confidence": "low",
  "narrative": "Starting from a short-term base-rate anchored by 2025 toll and Feb 2026 tallies, March fatalities would need a sustained high-rate or a single large incident to reach 900. Upward weather and crossing-risk push the odds up, but reporting lags and SAR improvements pull them back, yielding a 71% posterior with notable uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class is short-term Mediterranean death forecasts Jan–Mar using IOM Missing Migrants data, anchored by ~2,108 annual toll (2025) and ~606 deaths by Feb 24, 2026."
    },
    "factor_updates": [
      {
        "factor": "Projected March death-rate pace continuation from Feb 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "To reach 900 by end-March, roughly 294 additional deaths are needed beyond late-February counts; a continuation of February's pace would raise the probability modestly."
      },
      {
        "factor": "Weather-driven risk in the Central Mediterranean (storms/sea state)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Storms and rough seas increase fatality risk; persistent adverse conditions would raise March fatalities."
      },
      {
        "factor": "Risk of a single large maritime disaster (one incident with hundreds of deaths)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A single catastrophic wreck could push March totals past 900 in one event, disproportionately affecting the total."
      },
      {
        "factor": "Improvements in search-and-rescue and safe passage policies",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Better SAR and safer routing could avert deaths, counterbalancing upward risks."
      },
      {
        "factor": "Counting/reporting revisions and data lag in IOM Missing Migrants Project",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Ongoing data reconciliation could adjust counts, but the net effect on March totals is uncertain and could move in either direction."
      },
      {
        "factor": "Policy developments increasing crossing risk (crackdowns or deterrence effects)",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Deterrence or crackdowns may push migrants to more dangerous routes, marginally increasing fatalities."
      }
    ],
    "synthesis_rationale": "Starting from a mid-range anchor (~35% prior to updates), the combination of modestly upward updates (pace continuation, weather, potential large disaster) and downward/inconclusive factors (SAR improvements, data lag) yields a central 0.71 posterior. Correlations among factors are acknowledged, and a 0.60–0.80 calibrated band reflects residual uncertainty and potential counting variability."
  }
}

{
  "probability": 0.71,
  "range_low": 0.60,
  "range_high": 0.82,
  "summary": [
    "Bayesian posterior anchored on Feb 2026 IOM Missing Migrants Project counts (~606 deaths) and historical tolls, yielding a 0.71 probability for reaching 900 by end-March.",
    "March would need approximately 294 additional fatalities beyond the late-February tally; a sustained high March death-rate would push the total toward 900.",
    "Weather/seas, North Africa crossing activity, and potential large single-incident risks push the probability upward, while SAR constraints and data-lag dampen the count and pull the probability downward.",
    "Calibrated probability is 71% with a plausible uncertainty range roughly 60–82%, reflecting data gaps and event-driven volatility."
  ],
  "confidence": "medium",
  "narrative": "Using a Bayesian integration of February 2026 counts and known risk factors, the posterior probability of reaching 900 Mediterranean migrant deaths by end-March is 71%. The estimate acknowledges potential March volatility, including weather and SAR dynamics, while data gaps and reporting differences temper the certainty."
  ,
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Base-rate anchor using IOM Missing Migrants Project counts through February 2026 (≈606 deaths) and context from historical tolls; this establishes a conservative starting point before factor updates."
    },
    "factor_updates": [
      {
        "factor": "Severe weather and high-sea conditions in the central Mediterranean",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Early 2026 featured deadly storms contributing to high fatality counts; persistent storms into March would raise likelihood of reaching 900."
      },
      {
        "factor": "Surge in perilous crossings from Libya/Tunisia increasing exposure",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Rising departures elevate risk of vessels capsizing, increasing fatalities if March remains hazardous."
      },
      {
        "factor": "Policy and SAR restrictions reducing rescue capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Tighter controls and limited search-and-rescue capacity can increase fatalities in potential incidents."
      },
      {
        "factor": "Data collection gaps and methodological differences",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "IOM counts may lag or differ across NGOs, which could undercount or delay updates toward 900."
      },
      {
        "factor": "Seasonal weather improvements reducing March fatalities",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Sea conditions typically ease toward spring, potentially lowering March fatalities relative to February."
      }
    ],
    "synthesis_rationale": "The 0.71 posterior reflects a net-updated probability from an anchor around 0.60, with multiple upward pressure factors (weather, crossings, SAR constraints) partially offset by downward pressures (data gaps, seasonal improvement). Correlation among weather and crossing risk amplifies the upward drift, while measurement uncertainty caps the confidence, yielding a mid-range calibrated probability."
  }
}

